function CumulativeRechargeItem:SetCellInfo(pLv)
    self.pLv = pLv
    local rewardsData = CumulativeRechargeMgr:GetLevelData(pLv)
    local acquired = CumulativeRechargeMgr:GetRewardAcquiredState(pLv)
    local curRechargeLv = CumulativeRechargeMgr:GetCurRechargeLevel()
    local unlock = pLv > checkNumber(curRechargeLv)
    self:RefreshMainRewards(pLv)
    self:RefreshSubRewards(pLv)
    self:RefreshState(pLv)
    --self:SetGoodsInfo(rewardsData, acquired)
end

---刷新主要奖励
function CumulativeRechargeItem:RefreshMainRewards(pLv)
    local mainRewards = CumulativeRechargeMgr:GetMainRewardsByLevel(pLv)
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetGoodsVoById(mainRewards.goodsId)
    local idType = GoodsUtils.GetIdType(goodsVo.id)
    
    if idType == Constants.IDType.CharacterCard or idType == Constants.IDType.CardSkin then
        KTool.SetActive(self.Item1, false)
        KTool.SetActive(self.RoleAndStyle, true)
        KTool.SetActive(self.BtnRole, idType == Constants.IDType.CharacterCard)
        KTool.SetActive(self.BtnStyle, idType == Constants.IDType.CardSkin)

        if idType == Constants.IDType.CharacterCard then
            SetButtonAction(self.BtnRole, function()
                KCookie.Set(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID, StoreConstants.OpenIds.CumulativeRecharge)
                Events.Broadcast(Constants.EventNames.StoreDialogClose)
                GachaponUtils.OpenDetail(goodsVo.id,{ { id = Constants.UITypeIds.StoreEntry } })
            end)
        elseif idType == Constants.IDType.CardSkin then
            SetButtonAction(self.BtnStyle, function()
                KCookie.Set(Constants.UICacheDataKeys.STORE_ENTRY_SELECTED_OPEN_ID, StoreConstants.OpenIds.CumulativeRecharge)
                Events.Broadcast(Constants.EventNames.StoreDialogClose)
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.CommonStylePreView,
                            parameters = {skinId = goodsVo.id},
                        },
                        {
                            {id = Constants.UITypeIds.StoreEntry}
                        }
                )
            end)
        end
        
        CfUtils.FillText(self.RoleAndStyleTextName, goodsVo.name)
        
    elseif idType == Constants.IDType.GoodsHeadOrFrame then
        self:RefreshMainRewardDynamicHead(goodsVo, mainRewards.num)
    else
        self:RefreshMainRewardCommon(goodsVo, mainRewards.num)
    end
end

---刷新主奖励通用节点
function CumulativeRechargeItem:RefreshMainRewardCommon(goodsVo, num)
    KTool.SetActive(self.Item1, true)
    KTool.SetActive(self.ImgBigIcon, true)
    KTool.SetActive(self.ImgBigQuality, true)
    KTool.SetActive(self.RoleAndStyle, false)
    CfUtils.FillImage(self.ImgBigIcon, goodsVo.photoPath)
    CfUtils.FillImage(self.ImgBigQuality, StoreUtils.GetGoodsBgByQuality(goodsVo.quality))
    CfUtils.FillText(self.MainTextName, goodsVo.name)
    CfUtils.FillText(self.MainTextNumber, 'x' .. num)
    SetButtonAction(self.ImgBigIcon, function ()
        GameUtils.ShowCommonTipsBoard(self.ImgBigIcon.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)
end

---刷新主要奖励头像/头像框
function CumulativeRechargeItem:RefreshMainRewardDynamicHead(goodsVo, num)
    CfUtils.SetActive(self.MainHeadSpineNode, true)
    CfUtils.SetActive(self.ImgBigIcon, false)
    KTool.SetActive(self.ImgBigQuality, false)
    CfUtils.FillText(self.MainTextName, goodsVo.name)
    CfUtils.FillText(self.MainTextNumber, 'x' .. num)

    local headEnv  = CfUtils.GetLuaScr(self.MainHeadSpineNode, "Game.Behaviours.CommonPlayerHeadNode")
    if headEnv then
        --种类区分：1头像2头像框3徽章4主题
        if checkNumber(goodsVo.kind) == 1 then
            headEnv:FreshHeadIcon(goodsVo.id, true)
        elseif checkNumber(goodsVo.kind) == 2  then
            headEnv:FreshFrame(goodsVo.id, true)
        end
        headEnv:SetCallBack(function ()
            GameUtils.ShowCommonTipsBoard(self.ImgIcon.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)
    end
end

