function CumulativeRechargeItem:RefreshSubRewards(pLv)
    local subRewards = CumulativeRechargeMgr:GetSubRewardsByLevel(pLv)
    if next(subRewards) == nil then
        CfUtils.SetScale(self.ImgBigIcon, Vector3(0.6, 0.6, 0.6))
        CfUtils.SetScale(self.MainHeadSpineNode, Vector3(0.6, 0.6, 0.6))
        CfUtils.SetActive(self.Item2, false)
        return
    end

    CfUtils.SetScale(self.ImgBigIcon, Vector3(0.5, 0.5, 0.5))
    CfUtils.SetScale(self.ImgIcon, Vector3(0.5, 0.5, 0.5))
    CfUtils.SetScale(self.SubHeadSpineNode, Vector3(0.5, 0.5, 0.5))
    CfUtils.SetActive(self.Item2, true)
    
    --现在次要奖励也改为只能显示一个了
    local reward = subRewards[1]
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetGoodsVoById(reward.goodsId)
    local idType = GoodsUtils.GetIdType(goodsVo.id)
    if idType == Constants.IDType.GoodsHeadOrFrame then
        self:RefreshSubRewardDynamicHead(goodsVo, reward.num)
    else
        self:RefreshSubRewardCommon(goodsVo, reward.num)
    end
end

