---刷新节点状态
function CumulativeRechargeItem:RefreshState(pLv)
    local acquired = CumulativeRechargeMgr:GetRewardAcquiredState(pLv)
    CfUtils.SetUISwitchImage(self.ImgEars1, acquired and 1 or 2)
    CfUtils.SetUISwitchImage(self.ImgEars2, acquired and 1 or 2)
    CfUtils.SetUISwitchImage(self.ImgFace, acquired and 1 or 2)
    
    if acquired then
        -- 已领取
        local mainRewards = CumulativeRechargeMgr:GetMainRewardsByLevel(pLv)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetGoodsVoById(mainRewards.goodsId)
        local idType = GoodsUtils.GetIdType(goodsVo.id)
        local spineType = idType == Constants.IDType.CharacterCard or idType == Constants.IDType.CardSkin
        KTool.SetActive(self.DisableMask, not spineType)
        KTool.SetActive(self.SpineCompleteMask, spineType)
        KTool.SetActive(self.Bottom, false)
        KTool.SetActive(self.UIFX_ItemCell, false)
        KTool.SetActive(self.ArrowNode, false)
        KTool.SetActive(self.AccumulatedRechargeTotal, false)
        return
    end

    KTool.SetActive(self.DisableMask, false)
    KTool.SetActive(self.SpineCompleteMask, false)
    KTool.SetActive(self.Bottom, true)
    KTool.SetActive(self.AccumulatedRechargeTotal, true)
    local curAmount = CumulativeRechargeMgr:GetCurRechargeValue()
    local targetAmount = CumulativeRechargeMgr:GetRechargeAmount(pLv)
    local payDiamondVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.FreeDiamondId)
    CfUtils.FillImage(self.AccImgIcon, payDiamondVo.photoPath)
    CfUtils.FillText(self.AccTextNumber, targetAmount)
    local fontStyleButton = KTool.GetComponent(self.BtnGet.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))
    
    if curAmount >= targetAmount then
        -- 可领取
        KTool.SetActive(self.BtnGet, true)
        KTool.SetActive(self.StateGroup, false)
        KTool.SetActive(self.UIFX_ItemCell, true)
        KTool.SetActive(self.ArrowNode, false)

        fontStyleButton:ResetFontStyle("B12", localize("领取"))
        
    else
        -- 不可领取
        KTool.SetActive(self.BtnGet, true)
        KTool.SetActive(self.ArrowNode, true)
        KTool.SetActive(self.UIFX_ItemCell, false)

        fontStyleButton:ResetFontStyle("B13", localize("未达成"))

        local showTips = false
        if pLv == 1 then
            showTips = true
        else
            local prevAmount = CumulativeRechargeMgr:GetRechargeAmount(pLv - 1)
            if curAmount >= prevAmount then
                showTips = true
            end
        end
        if showTips then
            KTool.SetActive(self.StateGroup, true)
            local text = localize("还需充值<color=#ff1daa>_num_</color>_name_可获得", {_num_ = targetAmount - curAmount, _name_ = payDiamondVo.name})
            CfUtils.FillText(self.TxtNumber, text)
        else
            KTool.SetActive(self.StateGroup, false)
        end
    end
end

function CumulativeRechargeItem:SetGtnGet(pLv, rewardsData, acquired, unlock)
    local isShow = (not acquired) and (not unlock)
    KTool.SetActive(self.BtnGet.gameObject, isShow)
    if isShow then
        SetButtonAction(self.BtnGet, function()
            local configRowId = pLv
            CumulativeRechargeMgr:DrawReward(configRowId)
        end)
    end
end

function CumulativeRechargeItem:BtnGetOnClickHandler()
    local pLv = self.pLv
    local acquired = CumulativeRechargeMgr:GetRewardAcquiredState(pLv)
    if acquired then return end

    local curAmount = CumulativeRechargeMgr:GetCurRechargeValue()
    local targetAmount = CumulativeRechargeMgr:GetRechargeAmount(pLv)
    if targetAmount > curAmount then return end
    
    CumulativeRechargeMgr:DrawReward(pLv)
end

function CumulativeRechargeItem:SetGoodsInfo(rewardsData, acquired)
    if rewardsData then
        for i = 1, #self.listNodeRootFather do
            local goodsFather = self.listNodeRootFather[i]
            KTool.SetActive(goodsFather.gameObject, not isNull(rewardsData[i]))
            if rewardsData[i] then
                local goodNodeData = {
                    goodsId = rewardsData[i].goodsId, -- goodId
                    text = checkString( rewardsData[i].num), -- 数量显示,
                    isShowNo = true
                }
                local goodNode = self.listGoodCell[i]
                goodNode:Reload(goodNodeData)
                goodNode:SetSanXingGainShow(acquired)
                goodNode:SetClickButtonAction(function()
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodNodeData.goodsId)
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(goodNode.controller.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end)
            end
        end
    end
end
